import{_ as s,H as n,f as t,i}from"./chunks/framework.nyB-Xt5O.js";const h=JSON.parse('{"title":"可视化原理","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge-map/km-6-bi-visualization/01-principles.md","filePath":"knowledge-map/km-6-bi-visualization/01-principles.md","lastUpdated":1779798726000}'),e={name:"knowledge-map/km-6-bi-visualization/01-principles.md"};function l(o,a,p,r,c,d){return n(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="可视化原理" tabindex="-1">可视化原理 <a class="header-anchor" href="#可视化原理" aria-label="Permalink to &quot;可视化原理&quot;">​</a></h1><blockquote><p>好的可视化不是&quot;把数据画出来&quot;，而是<strong>利用人类视觉系统的特性</strong>来高效传递信息。理解底层认知原理，才能在设计图表时做出有理有据的决策。</p></blockquote><h2 id="格式塔原则-gestalt-principles" tabindex="-1">格式塔原则（Gestalt Principles） <a class="header-anchor" href="#格式塔原则-gestalt-principles" aria-label="Permalink to &quot;格式塔原则（Gestalt Principles）&quot;">​</a></h2><p>格式塔心理学描述了人类如何<strong>自动将视觉元素组织为整体</strong>。在仪表板设计中，这些原则是布局和信息分组的理论基础。</p><table tabindex="0"><thead><tr><th>原则</th><th>含义</th><th>可视化应用</th></tr></thead><tbody><tr><td><strong>接近性（Proximity）</strong></td><td>距离近的元素被视为一组</td><td>KPI 卡片放在一起表示同一主题</td></tr><tr><td><strong>相似性（Similarity）</strong></td><td>颜色/形状/大小相似的被视为一组</td><td>同一类别使用统一色系</td></tr><tr><td><strong>闭合性（Closure）</strong></td><td>大脑自动补全不完整的图形</td><td>散点图用轮廓圈出聚类</td></tr><tr><td><strong>连续性（Continuity）</strong></td><td>视觉倾向于沿平滑路径跟随</td><td>折线图的趋势线引导阅读</td></tr><tr><td><strong>图底关系（Figure-Ground）</strong></td><td>自动区分前景和背景</td><td>强调数据点与背景网格的对比</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">实践建议</p><p>在 Dashboard 布局时，先用接近性原则将相关 KPI 组合，再用相似性原则统一同类指标的视觉样式。<strong>不要依赖图例来建立关联</strong>——用户不会主动去看图例。</p></div><h2 id="预注意属性-pre-attentive-attributes" tabindex="-1">预注意属性（Pre-attentive Attributes） <a class="header-anchor" href="#预注意属性-pre-attentive-attributes" aria-label="Permalink to &quot;预注意属性（Pre-attentive Attributes）&quot;">​</a></h2><p>某些视觉属性可以在 <strong>200ms 以内</strong>被大脑并行处理，无需聚焦注意力。这些属性是实现&quot;一眼结论&quot;的关键。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>高效预注意属性（按效能排序）：</span></span>
<span class="line"><span>  颜色（色相/饱和度） &gt; 长度/宽度 &gt; 方向 &gt; 形状 &gt; 位置</span></span></code></pre></div><p><strong>编码优先级建议</strong>：</p><table tabindex="0"><thead><tr><th>数据类型</th><th>适合的预注意属性</th></tr></thead><tbody><tr><td>分类（Categorical）</td><td>色相（hue）、形状</td></tr><tr><td>有序（Ordinal）</td><td>饱和度（saturation）、亮度</td></tr><tr><td>数值（Quantitative）</td><td>长度、面积、位置（坐标轴）</td></tr><tr><td>异常值检测</td><td>色相（用高亮色）</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">常见误区</p><p>不要使用超过 <strong>6-8 种</strong> 不同颜色进行类别编码。预注意属性在数量过多时会退化为需要逐个识别的串行处理，失去效率优势。</p></div><h2 id="图表选择决策树-chart-selection-decision-tree" tabindex="-1">图表选择决策树（Chart Selection Decision Tree） <a class="header-anchor" href="#图表选择决策树-chart-selection-decision-tree" aria-label="Permalink to &quot;图表选择决策树（Chart Selection Decision Tree）&quot;">​</a></h2><p>选择图表的核心逻辑：<strong>数据类型 + 分析目标 → 图表类型</strong>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你想展示什么？</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 数值大小比较（Comparison）</span></span>
<span class="line"><span>│   ├── 单个类别 vs 目标 → 柱状图 + 参考线 / Bullet Chart</span></span>
<span class="line"><span>│   ├── 多类别之间 → 柱状图（排序后）</span></span>
<span class="line"><span>│   ├── 占比 → 条形图（不要用饼图超过 5 项）</span></span>
<span class="line"><span>│   └── 排名变化 → 条形图（横向，降序排列）</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 趋势与时间序列（Trend over Time）</span></span>
<span class="line"><span>│   ├── 连续时间 → 折线图</span></span>
<span class="line"><span>│   ├── 非连续时间点 → 柱状图</span></span>
<span class="line"><span>│   ├── 多序列对比 → 多线折线图（≤5 条线）</span></span>
<span class="line"><span>│   └── 周期模式 → 日历热力图</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 分布（Distribution）</span></span>
<span class="line"><span>│   ├── 单变量分布 → 直方图</span></span>
<span class="line"><span>│   ├── 多变量分布 → 箱线图（Box Plot）</span></span>
<span class="line"><span>│   ├── 数据密度 → 小提琴图（Violin Plot）+ 散点</span></span>
<span class="line"><span>│   └── 两个变量的关系 → 散点图 + 趋势线</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 构成（Composition）</span></span>
<span class="line"><span>│   ├── 静态占比 → 堆积柱状图 / Treemap</span></span>
<span class="line"><span>│   ├── 随时间变化 → 百分比堆积面积图</span></span>
<span class="line"><span>│   └── 层级关系 → Sunburst / Treemap</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── 关联与流动（Correlation / Flow）</span></span>
<span class="line"><span>    ├── 变量相关性 → 散点图矩阵（Scatter Matrix）</span></span>
<span class="line"><span>    ├── 地理分布 → 地图（Choropleth / Bubble Map）</span></span>
<span class="line"><span>    └── 流程/漏斗 → Sankey / Funnel Chart</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">决策要点</p><p>不存在&quot;最正确的图表&quot;，只有<strong>最诚实</strong>和<strong>最易懂</strong>的图表。选择时优先考虑<strong>目标读者的认知负担</strong>而非视觉新颖性。</p></div><h2 id="色彩理论-color-theory" tabindex="-1">色彩理论（Color Theory） <a class="header-anchor" href="#色彩理论-color-theory" aria-label="Permalink to &quot;色彩理论（Color Theory）&quot;">​</a></h2><h3 id="色彩在可视化中的三种角色" tabindex="-1">色彩在可视化中的三种角色 <a class="header-anchor" href="#色彩在可视化中的三种角色" aria-label="Permalink to &quot;色彩在可视化中的三种角色&quot;">​</a></h3><ol><li><strong>分类色（Categorical）</strong> — 区分不同类别，使用色相差异（如 D3 Category10）</li><li><strong>顺序色（Sequential）</strong> — 表示数值由低到高，使用单色相的亮度渐变（如浅蓝→深蓝）</li><li><strong>发散色（Diverging）</strong> — 表示偏离中心值的方向和程度（如红→白→蓝）</li></ol><h3 id="配色注意事项" tabindex="-1">配色注意事项 <a class="header-anchor" href="#配色注意事项" aria-label="Permalink to &quot;配色注意事项&quot;">​</a></h3><ul><li><strong>色盲友好（Colorblind Friendly）</strong>：避免红绿对比，改用蓝橙或蓝红组合</li><li><strong>统一语义</strong>：红色=异常/下降，绿色=正常/增长（在中国语境下反向也可，但要统一）</li><li><strong>背景色</strong>：使用浅灰/白色背景，不要在纯白背景上使用极浅色</li><li><strong>数据墨水比（Data-Ink Ratio）</strong>：减少非数据墨水（网格线、边框、装饰），让颜色全部分配给数据</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>好的配色：</span></span>
<span class="line"><span>  #4E79A7 (蓝)  #F28E2B (橙)  #E15759 (红)  #76B7B2 (青)</span></span>
<span class="line"><span>  #59A14F (绿)  #EDC948 (黄)  #B07AA1 (紫)  #FF9DA7 (粉)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>色盲友好（蓝橙）：</span></span>
<span class="line"><span>  #2B83BA → #FDAE61 → #D7191C</span></span>
<span class="line"><span>  (低 → 中 → 高)</span></span></code></pre></div><h2 id="标注基础-annotation-basics" tabindex="-1">标注基础（Annotation Basics） <a class="header-anchor" href="#标注基础-annotation-basics" aria-label="Permalink to &quot;标注基础（Annotation Basics）&quot;">​</a></h2><p>好的图表需要<strong>精确的标注</strong>来降低读者的理解成本。</p><ul><li><strong>标题（Title）</strong>：用陈述句而非名词短语，例如&quot;Q3 销售额同比增长 23%&quot;而非&quot;季度销售额&quot;</li><li><strong>数据标签（Data Label）</strong>：只在关键数据点标注，避免全部标注造成视觉混乱</li><li><strong>参考线（Reference Line）</strong>：标注目标值、平均值、阈值，帮助读者快速判断</li><li><strong>趋势线（Trend Line）</strong>：突出数据模式，配合置信区间</li><li><strong>异常标注（Anomaly Annotation）</strong>：在异常点添加说明文字，解释&quot;为什么&quot;</li></ul><div class="tip custom-block"><p class="custom-block-title">标注原则</p><p>如果读者需要超过 <strong>3 秒</strong> 才能理解图表想表达什么，说明标注不够。好的标注应该让读者在 1 秒内抓住核心信息。</p></div><h2 id="无障碍设计-accessibility-basics" tabindex="-1">无障碍设计（Accessibility Basics） <a class="header-anchor" href="#无障碍设计-accessibility-basics" aria-label="Permalink to &quot;无障碍设计（Accessibility Basics）&quot;">​</a></h2><p>可视化应当照顾视障和色觉障碍用户：</p><ul><li><strong>不止依赖颜色</strong>：使用形状、图案纹理（Pattern）辅助区分</li><li><strong>足够的对比度</strong>：前景/背景对比度至少 4.5:1（WCAG AA 标准）</li><li><strong>文本可缩放</strong>：确保文字在屏幕放大后依然清晰</li><li><strong>标题和图例</strong>：确保屏幕阅读器可以正确读取图表信息</li><li><strong>避免闪烁</strong>：避免高频率闪烁（可能诱发癫痫）</li></ul><h2 id="相关文章" tabindex="-1">相关文章 <a class="header-anchor" href="#相关文章" aria-label="Permalink to &quot;相关文章&quot;">​</a></h2><ul><li><a href="/data-analysis-learning/knowledge-map/km-6-bi-visualization/02-chart-types">图表类型详解</a> — 每种图表类型的适用场景与常见错误</li><li><a href="/data-analysis-learning/knowledge-map/km-6-bi-visualization/03-dashboard-design">Dashboard 设计</a> — 信息层级与布局最佳实践</li></ul>`,31)])])}const u=s(e,[["render",l]]);export{h as __pageData,u as default};
